import openpyxl
wb=openpyxl.load_workbook('init.xlsx')
from collections import defaultdict
sale=defaultdict(float); ret=defaultdict(float); br={}
for sh in ['STA','RPA','SR','SS']:
    ws=wb[sh]
    for r in range(2, ws.max_row+1):
        ty=ws.cell(r,3).value; or_=ws.cell(r,4).value
        key=(ty,or_)
        br[key]=ws.cell(r,2).value
        def num(v):
            if v is None or v=='-': return 0.0
            return float(v)
        sale[key] += num(ws.cell(r,5).value)
        ret[key] += num(ws.cell(r,6).value)
for k in sorted(sale, key=lambda x:str(x)):
    print(k, br[k], 'SALE', sale[k], 'RET', ret[k], 'BAL', sale[k]-ret[k])
"
